/* Memory detail sheet */
.memory-sheet {
  background: #ffffffe5;
  border-radius: 40px 40px 0 0;
  padding: 24px;
  backdrop-filter: blur(20px);
}

.memory-sheet__category {
  font: 500 12px/18px "SF Pro Text", -apple-system, sans-serif;
  color: #565c79;
}

.memory-sheet__text {
  font: 600 15px/22px "SF Pro Text", -apple-system, sans-serif;
  color: #1a1f3c;
}

.memory-sheet__provenance {
  font: 400 12px/18px "SF Pro Text", -apple-system, sans-serif;
  color: #717794;
}

/* The chat this memory came from, as a tappable citation */
.memory-sheet__citation {
  display: flex;
  align-items: center;
  gap: 8px;
  border-radius: 9999px;
  border: 1px solid #dddfeb;
  padding: 12px 16px;
}

