// The detail sheet. Provenance is a link back to the conversation the memory was
// derived from, which is what makes a memory auditable rather than asserted.

function MemoryDetailSheet({ memory, onDelete, onEdit }) {
  return (
    <Sheet>
      <h2 className="text-[18px] font-semibold">About the memory</h2>

      <p className="flex items-center gap-1.5 text-[12px] text-[--text-secondary]">
        <CategoryIcon name={memory.category.icon} />
        {memory.category.label}
      </p>

      <p className="text-[15px] font-semibold">{memory.text}</p>
      <p className="text-[12px] text-[--text-tertiary]">{memory.provenanceLabel}</p>

      {memory.sourceChat && (
        <a href={memory.sourceChat.href} className="flex items-center gap-2 rounded-full border px-4 py-3">
          <ChatIcon />
          <span className="truncate">{memory.sourceChat.title}</span>
        </a>
      )}

      <div className="flex gap-3">
        <Button variant="destructive" onClick={onDelete}>Delete memory</Button>
        <Button variant="secondary" onClick={onEdit}>Edit memory</Button>
      </div>
    </Sheet>
  );
}

