// Hand-translated from the extracted tokens — verify against the iOS UI kit.

struct MemoryDetailSheet: View {
    let memory: Memory

    var body: some View {
        VStack(alignment: .leading, spacing: 16) {
            Text("About the memory").font(.system(size: 18, weight: .semibold))

            Label(memory.category.label, systemImage: memory.category.symbol)
                .font(.system(size: 12, weight: .medium))
                .foregroundStyle(Color.textSecondary)

            Text(memory.text).font(.system(size: 15, weight: .semibold))
            Text(memory.provenanceLabel)
                .font(.system(size: 12))
                .foregroundStyle(Color.textTertiary)

            if let chat = memory.sourceChat {
                SourceChatChip(chat: chat)
            }

            HStack(spacing: 12) {
                Button("Delete memory", role: .destructive) {}
                Button("Edit memory") {}
            }
        }
        .padding(24)
        .presentationDetents([.medium])
    }
}
